    h, w = len(grid), len(grid[0])
    points = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] != 0]
    if not points:
        return [row[:] for row in grid]

    # The clues are colored diagonal stripes. The two possible stripe
    # coordinates are the anti-diagonal sum (r+c) and the main-diagonal
    # difference (c-r).
    candidates = []
    for direction in (1, -1):
        lines = {}
        for r, c, color in points:
            key = r + c if direction == 1 else c - r
            if key in lines and lines[key] != color:
                break
            lines[key] = color
        else:
            candidates.append((len(lines), direction, lines))
    if not candidates:
        raise ValueError('clues do not form monochromatic diagonal stripes')
    _, direction, known = max(candidates, key=lambda item: item[0])

    # A single clue color encodes a uniform field.
    if len(set(known.values())) == 1:
        color = next(iter(known.values()))
        return [[color] * w for _ in range(h)]

    # Infer the shortest period for which all residues are directly sampled
    # and every repeated residue agrees.
    for period in range(1, h + w + 1):
        motif = {}
        for key, color in known.items():
            residue = key % period
            if residue in motif and motif[residue] != color:
                break
            motif[residue] = color
        else:
